import{_ as e,o as a,c as s,a5 as i}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"DA-E06-06 - Redis Key Patterns","description":"","frontmatter":{},"headers":[],"relativePath":"database/redis-cache/DA-E06-06-redis-key-patterns.md","filePath":"database/redis-cache/DA-E06-06-redis-key-patterns.md"}'),r={name:"database/redis-cache/DA-E06-06-redis-key-patterns.md"};function d(n,t,l,o,h,c){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="da-e06-06-redis-key-patterns" tabindex="-1">DA-E06-06 - Redis Key Patterns <a class="header-anchor" href="#da-e06-06-redis-key-patterns" aria-label="Permalink to &quot;DA-E06-06 - Redis Key Patterns&quot;">​</a></h1><p><strong>Owner:</strong> An (AI)<br><strong>Priority:</strong> High<br><strong>Status:</strong> Source of truth for Redis key names, values, TTLs, and service ownership<br><strong>Blocks:</strong> DA-E11-03<br><strong>Blocked by:</strong> DA-E05-04</p><hr><h2 id="_1-purpose" tabindex="-1">1. Purpose <a class="header-anchor" href="#_1-purpose" aria-label="Permalink to &quot;1. Purpose&quot;">​</a></h2><p>This document defines the Redis key contracts used by BrandHub so services do not create overlapping keys, incompatible value formats, or mismatched TTL behavior.</p><p>Redis is a cache and coordination layer only. It must not become primary storage for users, workspaces, posts, billing data, or audit records.</p><hr><h2 id="_2-naming-rules" tabindex="-1">2. Naming Rules <a class="header-anchor" href="#_2-naming-rules" aria-label="Permalink to &quot;2. Naming Rules&quot;">​</a></h2><ul><li>Use lowercase namespace prefixes separated by <code>:</code>.</li><li>Put the highest-cardinality identifier at the end of the key.</li><li>Do not reuse a namespace for a different value shape.</li><li>Every key in this document must have a TTL.</li><li>Services must treat this document as the contract before adding new Redis keys.</li></ul><hr><h2 id="_3-key-pattern-summary" tabindex="-1">3. Key Pattern Summary <a class="header-anchor" href="#_3-key-pattern-summary" aria-label="Permalink to &quot;3. Key Pattern Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Family</th><th>Key template</th><th>Example key</th><th>Value type</th><th>Value content</th><th>TTL</th><th>Writes</th><th>Reads</th></tr></thead><tbody><tr><td>JWT blacklist</td><td><code>jwt:blacklist:{jti}</code></td><td><code>jwt:blacklist:01JZ9P2N8Y7Q4M5R6T0ABCDEF1</code></td><td>String</td><td><code>&quot;1&quot;</code>; only key existence matters</td><td><strong>15 minutes, equal to access token TTL</strong></td><td>business-service</td><td>api-gateway, business-service</td></tr><tr><td>Rate limiting</td><td><code>ratelimit:{userId}:{minute}</code></td><td><code>ratelimit:user_123:29740320</code></td><td>Integer string</td><td>Request count from Redis <code>INCR</code></td><td>60 seconds</td><td>api-gateway</td><td>api-gateway</td></tr><tr><td>OAuth state</td><td><code>oauth:state:{state}</code></td><td><code>oauth:state:9dfc2c7a-6d2c-4c89-88f1-99fd16a83df4</code></td><td>JSON string</td><td>OAuth flow metadata: provider, redirect URI, and optional PKCE/workspace context</td><td>10 minutes</td><td>business-service</td><td>business-service</td></tr><tr><td>Trending cache</td><td><code>trends:vn:{date}:{category}</code></td><td><code>trends:vn:2026-06-29:fashion</code></td><td>JSON string</td><td>Serialized list of trending topics/items for the date and category</td><td>6 hours</td><td>ai-service</td><td>ai-service</td></tr></tbody></table><p>&gt; Business-facing services should consume trending data through the ai-service internal endpoint, not by reading the Redis key directly. The Redis key owner is ai-service.</p><hr><h2 id="_4-jwt-blacklist" tabindex="-1">4. JWT Blacklist <a class="header-anchor" href="#_4-jwt-blacklist" aria-label="Permalink to &quot;4. JWT Blacklist&quot;">​</a></h2><h3 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Key template</td><td><code>jwt:blacklist:{jti}</code></td></tr><tr><td>Example key</td><td><code>jwt:blacklist:01JZ9P2N8Y7Q4M5R6T0ABCDEF1</code></td></tr><tr><td>Value type</td><td>String</td></tr><tr><td>Value content</td><td><code>&quot;1&quot;</code></td></tr><tr><td>TTL</td><td><strong>15 minutes</strong></td></tr><tr><td>Writer</td><td>business-service</td></tr><tr><td>Readers</td><td>api-gateway, business-service</td></tr></tbody></table><h3 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h3><ul><li>The key is written when an access token is revoked, for example logout or access-token rotation.</li><li>The value is always <code>&quot;1&quot;</code> because only key existence matters.</li><li><strong>The TTL must equal the access token TTL: 15 minutes.</strong></li><li>Do not keep access-token blacklist entries longer than the access token lifetime. They should expire naturally at the same time the token would have expired anyway.</li></ul><h3 id="redis-operation" tabindex="-1">Redis Operation <a class="header-anchor" href="#redis-operation" aria-label="Permalink to &quot;Redis Operation&quot;">​</a></h3><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SETEX jwt:blacklist:{jti} 900 &quot;1&quot;</span></span></code></pre></div><hr><h2 id="_5-rate-limiting" tabindex="-1">5. Rate Limiting <a class="header-anchor" href="#_5-rate-limiting" aria-label="Permalink to &quot;5. Rate Limiting&quot;">​</a></h2><h3 id="contract-1" tabindex="-1">Contract <a class="header-anchor" href="#contract-1" aria-label="Permalink to &quot;Contract&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Key template</td><td><code>ratelimit:{userId}:{minute}</code></td></tr><tr><td>Example key</td><td><code>ratelimit:user_123:29740320</code></td></tr><tr><td>Value type</td><td>Integer string</td></tr><tr><td>Value content</td><td>Request count for that user in that minute window</td></tr><tr><td>TTL</td><td>60 seconds</td></tr><tr><td>Writer</td><td>api-gateway</td></tr><tr><td>Reader</td><td>api-gateway</td></tr></tbody></table><p><code>{minute}</code> is the current epoch minute, calculated as <code>epoch_seconds / 60</code> using integer division.</p><h3 id="required-pattern" tabindex="-1">Required Pattern <a class="header-anchor" href="#required-pattern" aria-label="Permalink to &quot;Required Pattern&quot;">​</a></h3><p>Use Redis <code>INCR</code> + <code>EXPIRE</code>, setting the expiry only when the first increment creates the key. Do not use a Lua script for this task; the simpler pattern is the accepted implementation contract for DA-E11-03.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>count = INCR ratelimit:{userId}:{minute}</span></span>
<span class="line"><span>if count == 1:</span></span>
<span class="line"><span>  EXPIRE ratelimit:{userId}:{minute} 60</span></span>
<span class="line"><span>if count &gt; limit:</span></span>
<span class="line"><span>  reject with 429 RATE_LIMIT_EXCEEDED</span></span></code></pre></div><h3 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h3><ul><li>The gateway is the enforcement point.</li><li>Downstream services should not implement their own duplicate per-user request limiter for the same route group.</li><li>The default product limit is 100 requests per minute per authenticated user unless a route explicitly documents a stricter limit.</li></ul><hr><h2 id="_6-oauth-state" tabindex="-1">6. OAuth State <a class="header-anchor" href="#_6-oauth-state" aria-label="Permalink to &quot;6. OAuth State&quot;">​</a></h2><h3 id="contract-2" tabindex="-1">Contract <a class="header-anchor" href="#contract-2" aria-label="Permalink to &quot;Contract&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Key template</td><td><code>oauth:state:{state}</code></td></tr><tr><td>Example key</td><td><code>oauth:state:9dfc2c7a-6d2c-4c89-88f1-99fd16a83df4</code></td></tr><tr><td>Value type</td><td>JSON string</td></tr><tr><td>Value content</td><td>OAuth flow metadata</td></tr><tr><td>TTL</td><td>10 minutes</td></tr><tr><td>Writer</td><td>business-service</td></tr><tr><td>Reader</td><td>business-service</td></tr></tbody></table><h3 id="required-json-shape" tabindex="-1">Required JSON Shape <a class="header-anchor" href="#required-json-shape" aria-label="Permalink to &quot;Required JSON Shape&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;provider&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;google&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;redirectUri&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://app.brandhub.vn/oauth/callback&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;workspaceId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ws_123&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;userId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;user_123&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;codeVerifier&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pkce-code-verifier&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="rules-1" tabindex="-1">Rules <a class="header-anchor" href="#rules-1" aria-label="Permalink to &quot;Rules&quot;">​</a></h3><ul><li><code>provider</code> and <code>redirectUri</code> are required.</li><li><code>workspaceId</code>, <code>userId</code>, and <code>codeVerifier</code> are included when the OAuth flow needs workspace binding or PKCE.</li><li>Delete the key after a successful callback validation to enforce one-time use.</li><li>If the key is missing, expired, malformed, or mismatched, return <code>OAUTH_STATE_INVALID</code>.</li></ul><h3 id="redis-operation-1" tabindex="-1">Redis Operation <a class="header-anchor" href="#redis-operation-1" aria-label="Permalink to &quot;Redis Operation&quot;">​</a></h3><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SETEX oauth:state:{state} 600 &quot;{json}&quot;</span></span>
<span class="line"><span>DEL oauth:state:{state}</span></span></code></pre></div><hr><h2 id="_7-trending-analytics-cache" tabindex="-1">7. Trending / Analytics Cache <a class="header-anchor" href="#_7-trending-analytics-cache" aria-label="Permalink to &quot;7. Trending / Analytics Cache&quot;">​</a></h2><h3 id="contract-3" tabindex="-1">Contract <a class="header-anchor" href="#contract-3" aria-label="Permalink to &quot;Contract&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Key template</td><td><code>trends:vn:{date}:{category}</code></td></tr><tr><td>Example key</td><td><code>trends:vn:2026-06-29:fashion</code></td></tr><tr><td>Value type</td><td>JSON string</td></tr><tr><td>Value content</td><td>Serialized list of trend items</td></tr><tr><td>TTL</td><td>6 hours</td></tr><tr><td>Writer</td><td>ai-service</td></tr><tr><td>Reader</td><td>ai-service</td></tr></tbody></table><h3 id="required-json-shape-1" tabindex="-1">Required JSON Shape <a class="header-anchor" href="#required-json-shape-1" aria-label="Permalink to &quot;Required JSON Shape&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;keyword&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;summer outfit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;platform&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;google&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;region&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;VN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;score&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">87</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;fetchedAt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-06-29T00:00:00Z&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h3 id="rules-2" tabindex="-1">Rules <a class="header-anchor" href="#rules-2" aria-label="Permalink to &quot;Rules&quot;">​</a></h3><ul><li><code>{date}</code> must use UTC date format <code>YYYY-MM-DD</code>.</li><li><code>{category}</code> must be a lowercase category slug such as <code>fashion</code>, <code>food</code>, <code>beauty</code>, <code>tech</code>, or <code>lifestyle</code>.</li><li>Cache misses should trigger a live crawl when possible, then repopulate Redis.</li><li>If the live trends source fails, callers should prefer stale-but-available fallback data at the service layer instead of failing the product workflow.</li></ul><h3 id="redis-operation-2" tabindex="-1">Redis Operation <a class="header-anchor" href="#redis-operation-2" aria-label="Permalink to &quot;Redis Operation&quot;">​</a></h3><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SETEX trends:vn:{YYYY-MM-DD}:{category} 21600 &quot;{json}&quot;</span></span></code></pre></div><hr><h2 id="_8-ownership-matrix" tabindex="-1">8. Ownership Matrix <a class="header-anchor" href="#_8-ownership-matrix" aria-label="Permalink to &quot;8. Ownership Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Service</th><th>Redis role</th></tr></thead><tbody><tr><td>api-gateway</td><td>Reads JWT blacklist; writes and reads rate-limit counters</td></tr><tr><td>business-service</td><td>Writes JWT blacklist; writes, reads, and deletes OAuth state</td></tr><tr><td>ai-service</td><td>Writes and reads trending cache</td></tr><tr><td>publisher-service</td><td>No ownership of the four DA-E06-06 key families</td></tr></tbody></table><hr><h2 id="_9-acceptance-checklist" tabindex="-1">9. Acceptance Checklist <a class="header-anchor" href="#_9-acceptance-checklist" aria-label="Permalink to &quot;9. Acceptance Checklist&quot;">​</a></h2><ul><li>[x] JWT blacklist key pattern documented with template, example, value type, value content, TTL, readers, and writer</li><li>[x] Rate-limit key pattern documented with template, example, value type, value content, TTL, reader, and writer</li><li>[x] OAuth state key pattern documented with template, example, value type, value content, TTL, reader, and writer</li><li>[x] Trending cache key pattern documented with template, example, value type, value content, TTL, reader, and writer</li><li>[x] JWT blacklist TTL explicitly equals the access token TTL: 15 minutes</li><li>[x] Rate limiting explicitly uses <code>INCR</code> + <code>EXPIRE</code> on first increment, not Lua</li></ul>`,57)])])}const k=e(r,[["render",d]]);export{u as __pageData,k as default};
